package com.servicehub.api;
import com.servicehub.domain.*; import com.servicehub.repository.UserRepository; import com.servicehub.security.JwtService; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController { private final UserRepository users; private final JwtService jwt; private final BCryptPasswordEncoder encoder=new BCryptPasswordEncoder(); public AuthController(UserRepository u,JwtService j){users=u;jwt=j;} public record Credentials(@Email String email,@NotBlank String password){} public record AuthResponse(String accessToken,String name,Role role){} @PostMapping("/register") @ResponseStatus(HttpStatus.CREATED) public AuthResponse register(@RequestBody Credentials c){if(users.findByEmail(c.email()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Email already registered");AppUser u=new AppUser();u.setEmail(c.email());u.setDisplayName(c.email().split("@")[0]);u.setPasswordHash(encoder.encode(c.password()));u.setRole(Role.CUSTOMER);users.save(u);return new AuthResponse(jwt.issue(u),u.getDisplayName(),u.getRole());} @PostMapping("/login") public AuthResponse login(@RequestBody Credentials c){AppUser u=users.findByEmail(c.email()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid credentials"));if(!encoder.matches(c.password(),u.getPasswordHash()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid credentials");return new AuthResponse(jwt.issue(u),u.getDisplayName(),u.getRole());} }
